if(TowTrouble.RecoveryProfile.ValidationStorageKey!="TowTrouble.Validation.SteeringDirection")throw new System.Exception("Isolated scope required");
var session=UnityEngine.Object.FindFirstObjectByType<TowTrouble.DemoSession>();var world=session.World;var car=world.Drivers[0];var catalog=session.GarageCatalog;
var builds=System.Linq.Enumerable.Range(0,4).Select(i=>new TowTrouble.RecoveryBuild{Model=i}).Concat(catalog.Parts.Where(p=>p.Slot==TowTrouble.GarageSlot.Assembly&&p.Prefabs!=null&&p.Prefabs.Length>0).Select(p=>new TowTrouble.RecoveryBuild{Model=0,Items=new[]{p.Id}})).Concat(new[]{new TowTrouble.RecoveryBuild{Model=0}}).ToArray();
session.Profile.ownedParts=catalog.Parts.Select(p=>p.Id).ToList();
var input=typeof(TowTrouble.DemoSession).GetField("ValidationInput",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);
int index=0,stage=0;float next=0,deadline=UnityEngine.Time.realtimeSinceStartup+240;var checks=new System.Collections.Generic.List<object>();UnityEngine.Transform wheel=null;UnityEngine.Quaternion rest=default;UnityEngine.Vector3 hub=default;float rightAngle=0,leftAngle=0;float[] rightRoad=null,leftRoad=null;int geometryBefore=0;bool pictured=false,pictureThis=false;
System.Func<float> angle=()=>UnityEngine.Vector3.SignedAngle(rest*UnityEngine.Vector3.forward,wheel.localRotation*UnityEngine.Vector3.forward,rest*UnityEngine.Vector3.up);
System.Func<float[]> road=()=>System.Linq.Enumerable.Range(0,2).Select(i=>UnityEngine.Vector3.SignedAngle(UnityEngine.Vector3.right,car.transform.InverseTransformDirection(car.WheelVisual(i).right),UnityEngine.Vector3.up)).ToArray();
System.Action<string> capture=name=>{
 var go=new UnityEngine.GameObject("Validation steering close camera");var cam=go.AddComponent<UnityEngine.Camera>();cam.CopyFrom(UnityEngine.Camera.main);cam.enabled=false;cam.nearClipPlane=.025f;
 var rt=UnityEngine.RenderTexture.GetTemporary(900,700,24);var previous=UnityEngine.RenderTexture.active;
 try{cam.targetTexture=rt;cam.fieldOfView=55;var axis=wheel.parent.TransformDirection(rest*UnityEngine.Vector3.up);cam.transform.position=wheel.position+axis*.85f+car.transform.right*.18f;cam.transform.LookAt(wheel.position,car.transform.up);cam.Render();UnityEngine.RenderTexture.active=rt;var tex=new UnityEngine.Texture2D(rt.width,rt.height,UnityEngine.TextureFormat.RGB24,false);tex.ReadPixels(new UnityEngine.Rect(0,0,rt.width,rt.height),0,0);tex.Apply();System.IO.File.WriteAllBytes("/private/tmp/TowSteeringDirection/"+name+".png",tex.EncodeToPNG());UnityEngine.Object.Destroy(tex);}finally{UnityEngine.RenderTexture.active=previous;cam.targetTexture=null;UnityEngine.RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.Destroy(go);}
};
System.Action<bool,string> finish=(success,error)=>{input.SetValue(session,UnityEngine.Vector2.zero);System.IO.File.WriteAllText("/private/tmp/TowSteeringDirection/Gameplay.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success,error,total=builds.Length,checks},Newtonsoft.Json.Formatting.Indented));};
UnityEditor.EditorApplication.CallbackFunction tick=null;tick=()=>{try{
 float now=UnityEngine.Time.realtimeSinceStartup;if(now<next)return;if(now>deadline)throw new System.Exception("Timed out");if(!session.Connected){next=now+.2f;return;}
 var build=builds[index];var part=catalog.Find(build.Item(TowTrouble.GarageSlot.Assembly,catalog));string label=part!=null&&part.Prefabs.Length>0?part.EnglishName:TowTrouble.RecoveryVehicle.ModelNames[build.Model]+" Stock";
 if(stage==0){input.SetValue(session,UnityEngine.Vector2.zero);if(session.GarageOpen)session.CloseOverlay();car.SetSpawn(world.GaragePosition+new UnityEngine.Vector3(-2.5f,.12f,-2),UnityEngine.Quaternion.Euler(0,180,0));car.SetSimulation(true);session.Profile.vehicle=build.Model;world.SetDriver("Steering direction validation",build.Model,0);stage=1;next=now+.35f;return;}
 if(stage==1){session.OpenGarage();if(!session.GarageOpen)throw new System.Exception("Garage did not open: "+label);geometryBefore=car.GeometryVersion;session.PreviewGarage(build);stage=2;next=now+.2f;return;}
 if(stage==2){if(!session.GarageOpen)throw new System.Exception("Garage unexpectedly closed");if(!pictured&&label.Contains("Electron"))UnityEngine.ScreenCapture.CaptureScreenshot("/private/tmp/TowSteeringDirection/Garage-fit.png");session.CommitGarage(build);session.CloseOverlay();if(session.GarageOpen||UnityEngine.Time.timeScale==0)throw new System.Exception("Garage did not return to gameplay");stage=3;next=now+.35f;return;}
 if(stage==3){if(car.GeometryVersion<=geometryBefore)throw new System.Exception("Body did not rebind");wheel=car.GetComponentsInChildren<UnityEngine.MeshFilter>(true).Single(m=>m.sharedMesh.name.Contains("SteerWheel")&&TowTrouble.RecoveryVehicleEffects.VisiblePart(m.transform,car.transform)&&m.GetComponent<UnityEngine.MeshRenderer>().enabled).transform;rest=wheel.localRotation;hub=wheel.localPosition;pictureThis=!pictured&&label.Contains("Electron");input.SetValue(session,new UnityEngine.Vector2(1,.5f));stage=4;next=now+.7f;return;}
 if(stage==4){rightAngle=angle();rightRoad=road();if(rightAngle<90||rightRoad.Any(a=>a<5)||car.ControlInput.x<.8f)throw new System.Exception("Right direction mismatch: "+label+" steering "+rightAngle+" road "+string.Join(",",rightRoad));if(pictureThis)capture("Right");input.SetValue(session,new UnityEngine.Vector2(-1,.5f));stage=5;next=now+.7f;return;}
 if(stage==5){leftAngle=angle();leftRoad=road();if(leftAngle>-90||leftRoad.Any(a=>a>-5)||car.ControlInput.x>-.8f)throw new System.Exception("Left direction mismatch: "+label+" steering "+leftAngle+" road "+string.Join(",",leftRoad));if(UnityEngine.Vector3.Distance(hub,wheel.localPosition)>.001f)throw new System.Exception("Hub moved");if(pictureThis){capture("Left");pictured=true;}input.SetValue(session,UnityEngine.Vector2.zero);stage=6;next=now+.6f;return;}
 if(stage==6){float center=angle();var centeredRoad=road();if(UnityEngine.Mathf.Abs(center)>1||centeredRoad.Any(a=>UnityEngine.Mathf.Abs(a)>1))throw new System.Exception("No center return: "+label);checks.Add(new{index,label,model=car.ModelIndex,assembly=build.Item(TowTrouble.GarageSlot.Assembly,catalog),garagePreviewCommitClose=true,rightSteering=rightAngle,rightFrontWheels=rightRoad,leftSteering=leftAngle,leftFrontWheels=leftRoad,centerSteering=center,centerFrontWheels=centeredRoad,hubFixed=true,frame=UnityEngine.Time.frameCount});System.IO.File.WriteAllText("/private/tmp/TowSteeringDirection/Progress.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{completed=checks.Count,total=builds.Length,last=label}));index++;if(index==builds.Length){UnityEditor.EditorApplication.update-=tick;finish(true,null);}else{stage=0;next=now+.05f;}}
 }catch(System.Exception e){UnityEditor.EditorApplication.update-=tick;finish(false,e.GetBaseException().ToString());}};
UnityEditor.EditorApplication.update+=tick;return new{started=true,total=builds.Length,scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().name};
